    .io_trAddr     (_ctrl_io_trAddr),
    .io_trDataIn   (_ctrl_io_trDataIn),
    .io_trMask     (_ctrl_io_trMask),
    .io_accEnable  (_ctrl_io_accEnable),
    .io_accWrite   (_ctrl_io_accWrite),
    .io_accAddr    (_ctrl_io_accAddr),
    .io_accDataIn  (_ctrl_io_accDataIn),
    .io_accMask    (_ctrl_io_accMask)
  );
  TrSramArray trSram (
    .clock      (clock),
    .io_enable  (_ctrl_io_trEnable),
    .io_write   (_ctrl_io_trWrite),
    .io_addr    (_ctrl_io_trAddr),
    .io_dataIn  (_ctrl_io_trDataIn),
    .io_mask    (_ctrl_io_trMask),
    .io_dataOut (_ctrl_io_trDataOut)
  );
  AccSramArray accSram (
    .clock      (clock),
    .io_enable  (_ctrl_io_accEnable),
    .io_write   (_ctrl_io_accWrite),
    .io_addr    (_ctrl_io_accAddr),
    .io_dataIn  (_ctrl_io_accDataIn),
    .io_mask    (_ctrl_io_accMask),
    .io_dataOut (_ctrl_io_accDataOut)
  );
  assign io_readOut = io.readOut;
endmodule

module MmauSeq(
  input                                                                                                                                       clock,
                                                                                                                                              reset,
  output                                                                                                                                      io_task_ready,
  input                                                                                                                                       io_task_valid,
  input  struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; } io_task_bits,
  output                                                                                                                                      io_step,
                                                                                                                                              io_completed,
  output struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[3:0]    io_addrAs,
  output struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0]    io_addrBs,
                                                                                                                                              io_addrCs,
                                                                                                                                              io_addrOs
);

  wire
    struct packed {struct packed {logic ready; logic valid; struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; } bits; } task_0; logic halt; logic step; logic completed; struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[3:0] addrAs; struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0] addrBs; struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0] addrCs; struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0] addrOs; }
    io;
  reg  [1:0] counter;
  reg  [9:0] buffer;
  wire       step = &counter;
  wire       beforeStep = counter == 2'h2;
  reg  [1:0] state;
  wire       isIdle = state == 2'h0;
  wire       isSingle = state == 2'h1;
  wire       isDouble = state == 2'h2;
  wire       fire = io.task_0.ready & io.task_0.valid;
  struct packed {struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; } task_0; logic [1:0] phase; logic [9:0] counter; }[1:0]
    tasks;
  reg        taskWritePtr;
  wire       taskInfo_isWriteTarget_1 = taskWritePtr;
  wire       taskCurrentPtr = isSingle ^ taskWritePtr;
  wire       taskInfo_isCurrent_1 = taskCurrentPtr;
  wire       taskPendingPtr = ~taskCurrentPtr;
  struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[3:0]
    ctrlAs;
  struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0]
    ctrlBs;
  struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0]
    ctrlCs;
  struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0]
    ctrlOs;
  wire       taskInfo_isWriteTarget = ~taskWritePtr;
  wire       taskInfo_isWrite = taskInfo_isWriteTarget & fire;
  wire       taskInfo_isCurrent = ~taskCurrentPtr;
  wire       ctrlCs_0_useCurrent = tasks[taskCurrentPtr].phase == 2'h1;
  wire       _ctrlOs_0_ctrl_valid_T_1 = tasks[taskCurrentPtr].phase == 2'h2;
  wire [9:0] _taskInfo_waitForOther_T_11 =
    tasks[taskCurrentPtr].task_0.size - tasks[taskCurrentPtr].counter;
  wire       taskInfo_0_2 =
    ~taskInfo_isCurrent
    & (ctrlCs_0_useCurrent | _ctrlOs_0_ctrl_valid_T_1
       & _taskInfo_waitForOther_T_11 > tasks[1'h0].task_0.size);
  wire       taskInfo_halt = ~step | taskInfo_0_2;
  wire       _taskInfo_T_5 = tasks[1'h0].phase == 2'h2;
  wire       _taskInfo_T_1 = tasks[1'h0].phase == 2'h1;
  wire [9:0] _taskInfo_T_2 = tasks[1'h0].task_0.size - 10'h1;
  wire       _taskInfo_T_6 = tasks[1'h0].counter == 10'h3;
  wire       taskInfo_0_1 =
    _taskInfo_T_5
    & (_taskInfo_T_1 & tasks[1'h0].counter == _taskInfo_T_2 | _taskInfo_T_5
       & _taskInfo_T_6);
  wire       taskInfo_isWrite_1 = taskInfo_isWriteTarget_1 & fire;
  wire       taskInfo_1_2 =
    ~taskInfo_isCurrent_1
    & (ctrlCs_0_useCurrent | _ctrlOs_0_ctrl_valid_T_1
       & _taskInfo_waitForOther_T_11 > tasks[1'h1].task_0.size);
  wire       taskInfo_halt_1 = ~step | taskInfo_1_2;
  wire       _taskInfo_T_16 = tasks[1'h1].phase == 2'h2;
  wire       _taskInfo_T_12 = tasks[1'h1].phase == 2'h1;
  wire [9:0] _taskInfo_T_13 = tasks[1'h1].task_0.size - 10'h1;
  wire       _taskInfo_T_17 = tasks[1'h1].counter == 10'h3;
  wire       taskInfo_1_1 =
    _taskInfo_T_16
    & (_taskInfo_T_12 & tasks[1'h1].counter == _taskInfo_T_13 | _taskInfo_T_16
       & _taskInfo_T_17);
  wire [1:0] taskCmpls = {taskInfo_1_1, taskInfo_0_1};
  wire [1:0] taskWaits = {{taskInfo_1_2}, {taskInfo_0_2}};
  wire       _ctrlCs_0_baseValid_T_2 = tasks[taskPendingPtr].phase == 2'h1;
  wire [4:0] _ctrlAs_0_ctrl_addr_reg_T_1 =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.src1
      : tasks[taskPendingPtr].task_0.src1;
  wire [9:0] _ctrlAs_0_ctrl_addr_entry_T_1 =
    ctrlCs_0_useCurrent ? tasks[taskCurrentPtr].counter : tasks[taskPendingPtr].counter;
  wire [2:0] _ctrlAs_0_ctrl_mode_T_1 =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.mode
      : tasks[taskPendingPtr].task_0.mode;
  wire       _ctrlAs_0_ctrl_signed_T_1 =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.signed_0
      : tasks[taskPendingPtr].task_0.signed_0;
  wire [4:0] _ctrlBs_0_ctrl_addr_reg_T_1 =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.src2
      : tasks[taskPendingPtr].task_0.src2;
  wire [9:0] _ctrlBs_0_ctrl_addr_entry_T_1 =
    ctrlCs_0_useCurrent ? tasks[taskCurrentPtr].counter : tasks[taskPendingPtr].counter;
  wire [2:0] _ctrlBs_0_ctrl_mode_T_1 =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.mode
      : tasks[taskPendingPtr].task_0.mode;
  wire       _ctrlBs_0_ctrl_signed_T_1 =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.signed_0
      : tasks[taskPendingPtr].task_0.signed_0;
  wire       ctrlCs_0_baseValid =
    isSingle & ctrlCs_0_useCurrent | isDouble
    & (ctrlCs_0_useCurrent | _ctrlCs_0_baseValid_T_2 & ~taskWaits[taskPendingPtr]);
  wire [9:0] ctrlCs_0_entry =
    ctrlCs_0_useCurrent ? tasks[taskCurrentPtr].counter : tasks[taskPendingPtr].counter;
  wire [4:0] _ctrlCs_0_ctrl_addr_reg_T =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.dest
      : tasks[taskPendingPtr].task_0.dest;
  wire [2:0] _ctrlCs_0_ctrl_mode_T =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.mode
      : tasks[taskPendingPtr].task_0.mode;
  wire       _ctrlCs_0_ctrl_signed_T =
    ctrlCs_0_useCurrent
      ? tasks[taskCurrentPtr].task_0.signed_0
      : tasks[taskPendingPtr].task_0.signed_0;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & (&taskCmpls)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: 2 Tasks should not complete at the same time!\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  wire       taskCompleted = (|taskCmpls) & step;
  wire
    struct packed {logic ready; logic valid; struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; } bits; }
    _GEN =
    '{ready: (~isDouble | (|taskCmpls) & step), valid: io_task_valid, bits: io_task_bits};
  wire struct packed {logic [4:0] reg_0; logic [9:0] entry; } _GEN_0 =
    '{reg_0: _ctrlAs_0_ctrl_addr_reg_T_1, entry: _ctrlAs_0_ctrl_addr_entry_T_1};
  wire
    struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }
    ctrlAs_0_ctrl =
    '{valid:
        (isSingle & ctrlCs_0_useCurrent | isDouble
         & (ctrlCs_0_useCurrent | _ctrlCs_0_baseValid_T_2 & ~taskWaits[taskPendingPtr])),
      addr: _GEN_0,
      mode: _ctrlAs_0_ctrl_mode_T_1,
      signed_0: _ctrlAs_0_ctrl_signed_T_1};
  wire struct packed {logic [4:0] reg_0; logic [9:0] entry; } _GEN_1 =
    '{reg_0: _ctrlBs_0_ctrl_addr_reg_T_1, entry: _ctrlBs_0_ctrl_addr_entry_T_1};
  wire
    struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }
    ctrlBs_0_ctrl =
    '{valid:
        (isSingle & ctrlCs_0_useCurrent | isDouble
         & (ctrlCs_0_useCurrent | _ctrlCs_0_baseValid_T_2 & ~taskWaits[taskPendingPtr])),
      addr: _GEN_1,
      mode: _ctrlBs_0_ctrl_mode_T_1,
      signed_0: _ctrlBs_0_ctrl_signed_T_1};
  wire struct packed {logic [4:0] reg_0; logic [9:0] entry; } _GEN_2 =
    '{reg_0: _ctrlCs_0_ctrl_addr_reg_T, entry: ctrlCs_0_entry};
  wire
    struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }
    ctrlCs_0_ctrl =
    '{valid: (ctrlCs_0_baseValid & ctrlCs_0_entry < 10'h4),
      addr: _GEN_2,
      mode: _ctrlCs_0_ctrl_mode_T,
      signed_0: _ctrlCs_0_ctrl_signed_T};
  wire struct packed {logic [4:0] reg_0; logic [9:0] entry; } _GEN_3 =
    '{reg_0: tasks[taskCurrentPtr].task_0.dest, entry: tasks[taskCurrentPtr].counter};
  wire
    struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }
    ctrlOs_0_ctrl =
    '{valid:
        (isSingle & _ctrlOs_0_ctrl_valid_T_1 | isDouble
         & (_ctrlOs_0_ctrl_valid_T_1 | tasks[taskPendingPtr].phase == 2'h2)),
      addr: _GEN_3,
      mode: tasks[taskCurrentPtr].task_0.mode,
      signed_0: tasks[taskCurrentPtr].task_0.signed_0};
  assign io =
    '{task_0: _GEN,
      halt: (1'h0),
      step: step,
      completed: taskCompleted,
      addrAs: ctrlAs,
      addrBs: ctrlBs,
      addrCs: ctrlCs,
      addrOs: ctrlOs};
  wire
    struct packed {logic valid; struct packed {logic [4:0] reg_0; logic [9:0] entry; } addr; logic [2:0] mode; logic signed_0; }[7:0]
    _ctrlBs_WIRE =
    '{'{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
      '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
      '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
      '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
      '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
      '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
      '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
      '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0}};
  wire [1:0] _state_T_7 = taskCompleted & ~io.task_0.valid ? 2'h1 : 2'h2;
  wire [1:0] _state_T_10 = isDouble ? _state_T_7 : 2'h0;
  wire [1:0] _state_T_3 = io.task_0.valid ? 2'h2 : {1'h0, ~taskCompleted};
  wire [1:0] _state_T_4 = io.task_0.valid & taskCompleted ? 2'h1 : _state_T_3;
  wire [1:0] _state_T_9 = isSingle ? _state_T_4 : 2'h0;
  wire [9:0] _taskInfo_tasks_1_counter_T_16 =
    tasks[1'h1].phase == 2'h0 | _taskInfo_T_12 & tasks[1'h1].counter == _taskInfo_T_13
    | _taskInfo_T_16 & _taskInfo_T_17
      ? 10'h0
      : tasks[1'h1].counter + 10'h1;
  wire [9:0] _taskInfo_tasks_1_counter_T_17 =
    taskInfo_halt_1 ? tasks[1'h1].counter : _taskInfo_tasks_1_counter_T_16;
  wire [9:0] _taskInfo_tasks_1_counter_T_18 =
    taskInfo_isWrite_1 ? 10'h0 : _taskInfo_tasks_1_counter_T_17;
  wire [1:0] _taskInfo_tasks_1_phase_T_32 =
    taskInfo_halt_1
    | ~(_taskInfo_T_12 & tasks[1'h1].counter == _taskInfo_T_13 | _taskInfo_T_16
        & _taskInfo_T_17)
      ? tasks[1'h1].phase
      : {_taskInfo_T_12, 1'h0};
  wire [1:0] _taskInfo_tasks_1_phase_T_33 =
    _taskInfo_T_16
    & (_taskInfo_T_12 & tasks[1'h1].counter == _taskInfo_T_13 | _taskInfo_T_16
       & _taskInfo_T_17) & step
      ? 2'h0
      : _taskInfo_tasks_1_phase_T_32;
  wire [1:0] _taskInfo_tasks_1_phase_T_34 =
    taskInfo_isWrite_1 ? 2'h1 : _taskInfo_tasks_1_phase_T_33;
  wire
    struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; }
    _taskInfo_tasks_1_task_T = taskInfo_isWrite_1 ? io.task_0.bits : tasks[1'h1].task_0;
  wire [9:0] _taskInfo_tasks_0_counter_T_16 =
    tasks[1'h0].phase == 2'h0 | _taskInfo_T_1 & tasks[1'h0].counter == _taskInfo_T_2
    | _taskInfo_T_5 & _taskInfo_T_6
      ? 10'h0
      : tasks[1'h0].counter + 10'h1;
  wire [9:0] _taskInfo_tasks_0_counter_T_17 =
    taskInfo_halt ? tasks[1'h0].counter : _taskInfo_tasks_0_counter_T_16;
  wire [9:0] _taskInfo_tasks_0_counter_T_18 =
    taskInfo_isWrite ? 10'h0 : _taskInfo_tasks_0_counter_T_17;
  wire [1:0] _taskInfo_tasks_0_phase_T_32 =
    taskInfo_halt
    | ~(_taskInfo_T_1 & tasks[1'h0].counter == _taskInfo_T_2 | _taskInfo_T_5
        & _taskInfo_T_6)
      ? tasks[1'h0].phase
      : {_taskInfo_T_1, 1'h0};
  wire [1:0] _taskInfo_tasks_0_phase_T_33 =
    _taskInfo_T_5
    & (_taskInfo_T_1 & tasks[1'h0].counter == _taskInfo_T_2 | _taskInfo_T_5
       & _taskInfo_T_6) & step
      ? 2'h0
      : _taskInfo_tasks_0_phase_T_32;
  wire [1:0] _taskInfo_tasks_0_phase_T_34 =
    taskInfo_isWrite ? 2'h1 : _taskInfo_tasks_0_phase_T_33;
  wire
    struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; }
    _taskInfo_tasks_0_task_T = taskInfo_isWrite ? io.task_0.bits : tasks[1'h0].task_0;
  always @(posedge clock) begin
    if (reset) begin
      counter <= 2'h0;
      buffer <= 10'h0;
      state <= 2'h0;
      tasks <=
        '{'{task_0:
              '{src1: 5'h0,
                src2: 5'h0,
                dest: 5'h0,
                size: 10'h0,
                mode: 3'h0,
                signed_0: 1'h0,
                sa: 1'h0},
            phase: 2'h0,
            counter: 10'h0},
          '{task_0:
              '{src1: 5'h0,
                src2: 5'h0,
                dest: 5'h0,
                size: 10'h0,
                mode: 3'h0,
                signed_0: 1'h0,
                sa: 1'h0},
            phase: 2'h0,
            counter: 10'h0}};
      taskWritePtr <= 1'h0;
      ctrlAs <=
        '{'{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
          '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
          '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0},
          '{valid: 1'h0, addr: '{reg_0: 5'h0, entry: 10'h0}, mode: 3'h0, signed_0: 1'h0}};
      ctrlBs <= _ctrlBs_WIRE;
      ctrlCs <= _ctrlBs_WIRE;
      ctrlOs <= _ctrlBs_WIRE;
    end
    else begin
      counter <= isIdle & ~(|buffer) | step ? 2'h0 : counter + 2'h1;
      if (|tasks[taskCurrentPtr].phase)
        buffer <= tasks[taskCurrentPtr].task_0.size - 10'h1;
      else if (isIdle) begin
        if (step & (|buffer))
          buffer <= buffer - 10'h1;
      end
      else
        buffer <= 10'h0;
      state <= {1'h0, isIdle & io.task_0.valid} | _state_T_9 | _state_T_10;
      tasks[1'h1] <=
        '{task_0: _taskInfo_tasks_1_task_T,
          phase: _taskInfo_tasks_1_phase_T_34,
          counter: _taskInfo_tasks_1_counter_T_18};
      tasks[1'h0] <=
        '{task_0: _taskInfo_tasks_0_task_T,
          phase: _taskInfo_tasks_0_phase_T_34,
          counter: _taskInfo_tasks_0_counter_T_18};
      taskWritePtr <= taskWritePtr ^ fire;
      if (step) begin
        ctrlAs[2'h3] <= ctrlAs[2'h2];
        ctrlAs[2'h2] <= ctrlAs[2'h1];
        ctrlAs[2'h1] <= ctrlAs[2'h0];
        ctrlAs[2'h0] <= ctrlAs_0_ctrl;
        ctrlBs[3'h7] <= ctrlBs[3'h6];
        ctrlBs[3'h6] <= ctrlBs[3'h5];
        ctrlBs[3'h5] <= ctrlBs[3'h4];
        ctrlBs[3'h4] <= ctrlBs[3'h3];
        ctrlBs[3'h3] <= ctrlBs[3'h2];
        ctrlBs[3'h2] <= ctrlBs[3'h1];
        ctrlBs[3'h1] <= ctrlBs[3'h0];
        ctrlBs[3'h0] <= ctrlBs_0_ctrl;
        ctrlCs[3'h7] <= ctrlCs[3'h6];
        ctrlCs[3'h6] <= ctrlCs[3'h5];
        ctrlCs[3'h5] <= ctrlCs[3'h4];
        ctrlCs[3'h4] <= ctrlCs[3'h3];
        ctrlCs[3'h3] <= ctrlCs[3'h2];
        ctrlCs[3'h2] <= ctrlCs[3'h1];
        ctrlCs[3'h1] <= ctrlCs[3'h0];
        ctrlCs[3'h0] <= ctrlCs_0_ctrl;
        ctrlOs[3'h7] <= ctrlOs[3'h6];
        ctrlOs[3'h6] <= ctrlOs[3'h5];
        ctrlOs[3'h5] <= ctrlOs[3'h4];
        ctrlOs[3'h4] <= ctrlOs[3'h3];
        ctrlOs[3'h3] <= ctrlOs[3'h2];
        ctrlOs[3'h2] <= ctrlOs[3'h1];
        ctrlOs[3'h1] <= ctrlOs[3'h0];
        ctrlOs[3'h0] <= ctrlOs_0_ctrl;
      end
    end
  end // always @(posedge)
  assign io_task_ready = io.task_0.ready;
  assign io_step = io.step;
  assign io_completed = io.completed;
  assign io_addrAs = io.addrAs;
  assign io_addrBs = io.addrBs;
  assign io_addrCs = io.addrCs;
  assign io_addrOs = io.addrOs;
endmodule

module Mau16ShuffleMask(
  input  [2:0]           io_mode,
  input  [1:0][3:0][5:0] io_a,
                         io_b,
  output [1:0][3:0][5:0] io_aOut,
                         io_bOut
);

  wire
    struct packed {logic [2:0] mode; logic [1:0][3:0][5:0] a; logic [1:0][3:0][5:0] b; logic [1:0][3:0][5:0] aOut; logic [1:0][3:0][5:0] bOut; }
    io;
  wire
    struct packed {logic int4; logic int8; logic e5m2; logic e4m3; logic int16; logic fp4; logic fp16; logic bf16; }
    op;
  assign op =
    '{int4: (io.mode == 3'h0),
      int8: (io.mode == 3'h1),
      e5m2: (io.mode == 3'h2),
      e4m3: (io.mode == 3'h3),
      int16: (io.mode == 3'h4),
      fp4: (io.mode == 3'h5),
      fp16: (io.mode == 3'h6),
