module RoundedBucketRShifter(
  input  [15:0] io_input,
  input  [3:0]  io_amt,
  output [15:0] io_output
);

  wire struct packed {logic [15:0] input_0; logic [3:0] amt; logic [15:0] output_0; } io;
  wire [4:0][15:0] intermediate;
  wire [15:0]      _intermediate_1_T_2 =
    io.amt[0] ? {1'h0, intermediate[3'h0][15:1]} : intermediate[3'h0];
  wire [15:0]      _intermediate_2_T_2 =
    io.amt[1] ? {2'h0, intermediate[3'h1][15:2]} : intermediate[3'h1];
  wire [15:0]      _intermediate_3_T_2 =
    io.amt[2] ? {4'h0, intermediate[3'h2][15:4]} : intermediate[3'h2];
  wire [15:0]      _intermediate_4_T_2 =
    io.amt[3] ? {8'h0, intermediate[3'h3][15:8]} : intermediate[3'h3];
  assign intermediate =
    {{_intermediate_4_T_2},
     {_intermediate_3_T_2},
     {_intermediate_2_T_2},
     {_intermediate_1_T_2},
     {io.input_0}};
  wire             _guard_T = io.amt == 4'h0;
  wire [31:0]      lostMask = _guard_T ? 32'h0 : (32'h1 << io.amt) - 32'h1;
  wire [15:0]      lost = intermediate[3'h0] & lostMask[15:0];
  wire [3:0]       guardShift = _guard_T ? 4'h0 : io.amt - 4'h1;
  wire [15:0]      _guard_T_1 = lost >> guardShift;
  wire             guard = ~_guard_T & _guard_T_1[0];
  wire [31:0]      stickyMask = io.amt < 4'h2 ? 32'h0 : (32'h1 << guardShift) - 32'h1;
  wire             sticky = |(lost & stickyMask[15:0]);
  wire             roundUp = guard & (sticky | intermediate[3'h4][0]);
  assign io =
    '{input_0: io_input, amt: io_amt, output_0: (intermediate[3'h4] + {15'h0, roundUp})};
  assign io_output = io.output_0;
endmodule

