module Normalize(
  input  [31:0] io_inData,
  input  [2:0]  io_mode,
  output [31:0] io_outData,
  output        io_isNormalized,
                io_isSpecial
);

  wire
    struct packed {logic [31:0] inData; logic [2:0] mode; logic [31:0] outData; logic isNormalized; logic isSpecial; logic [4:0] flag; }
    io;
  wire
    struct packed {logic int4; logic int8; logic e5m2; logic e4m3; logic int16; logic fp4; logic fp16; logic bf16; }
    op;
  assign op =
    '{int4: (io.mode == 3'h0),
      int8: (io.mode == 3'h1),
      e5m2: (io.mode == 3'h2),
      e4m3: (io.mode == 3'h3),
      int16: (io.mode == 3'h4),
      fp4: (io.mode == 3'h5),
      fp16: (io.mode == 3'h6),
      bf16: (&io.mode)};
  wire        _GEN = op.e5m2 | op.e4m3 | op.fp4 | op.fp16 | op.bf16;
  wire        sign = io.inData[31];
  wire [7:0]  expRaw = io.inData[30:23];
  wire [22:0] manRaw = io.inData[22:0];
  wire        _isInf_T_1 = manRaw == 23'h0;
  wire        isZero = expRaw == 8'h0 & _isInf_T_1;
  wire        isInf = (&expRaw) & _isInf_T_1;
  wire        isNaN = (&expRaw) & (|manRaw);
  wire        isOverflow = expRaw > 8'hFD;
  wire        isUnderflow = expRaw == 8'h0;
  assign io =
    '{inData: io_inData,
      mode: io_mode,
      outData: io.inData,
      isNormalized: _GEN,
      isSpecial: (_GEN & (isZero | isInf | isNaN)),
      flag: (5'h0)};
  assign io_outData = io.outData;
  assign io_isNormalized = io.isNormalized;
  assign io_isSpecial = io.isSpecial;
endmodule

