    requestReg;
  reg  [2:0] mBlockReg;
  reg  [2:0] nBlockReg;
  wire [6:0] mBlockCount = (requestReg.m + 7'hF) / 7'h10;
  wire [6:0] nBlockCount = (requestReg.n + 7'h1F) / 7'h20;
  wire [6:0] kBlockCount = (requestReg.k + 7'h3) / 7'h4;
  wire [6:0] sequencerSteps = kBlockCount < 7'h8 ? 7'h8 : kBlockCount;
