    wire _GEN_4 = _GEN & ~reset;
    always @(posedge clock) begin
      if (_GEN_4
          & ~((|io.request.bits.m) & (|io.request.bits.n) & (|io.request.bits.k))) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: GEMM dimensions must be non-zero\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN_4
          & ~(io.request.bits.m < 7'h41 & io.request.bits.n < 7'h41
              & io.request.bits.k < 7'h41)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: GEMM dimensions exceed the AME v0.5 contract\n");
        if (`STOP_COND_)
          $fatal;
      end
