  `endif // not def SYNTHESIS
  wire
    struct packed {logic ready; logic valid; struct packed {struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; } task_0; logic [6:0] m; logic [6:0] n; logic [6:0] k; } bits; }
    _GEN_5 = '{ready: (state == 2'h0), valid: io_request_valid, bits: io_request_bits};
  wire
    struct packed {logic [4:0] src1; logic [4:0] src2; logic [4:0] dest; logic [9:0] size; logic [2:0] mode; logic signed_0; logic sa; }
    _GEN_6 =
    '{src1: requestReg.task_0.src1,
      src2: requestReg.task_0.src2,
      dest: requestReg.task_0.dest,
      size: {3'h0, sequencerSteps},
      mode: requestReg.task_0.mode,
      signed_0: requestReg.task_0.signed_0,
